package com.campusiq.platform.client; import com.fasterxml.jackson.annotation.JsonIgnoreProperties; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.util.*;
@Component public class CodeforcesClient {private final RestClient http; public CodeforcesClient(RestClient.Builder b,@Value("${platform.codeforces.base-url}")String u){http=b.baseUrl(u).build();} public InfoResponse info(String u){return get("/api/user.info?handles="+u,InfoResponse.class);} public StatusResponse status(String u){return get("/api/user.status?handle="+u,StatusResponse.class);} private <T>T get(String p,Class<T>t){try{return http.get().uri(p).retrieve().body(t);}catch(Exception e){throw new PlatformClientException("Codeforces is unavailable or returned an invalid response",e);}} @JsonIgnoreProperties(ignoreUnknown=true) public record InfoResponse(String status,List<UserInfo> result,String comment){} @JsonIgnoreProperties(ignoreUnknown=true) public record UserInfo(String handle,String firstName,String lastName,Long rating,String rank,Long contribution,Long maxRating){} @JsonIgnoreProperties(ignoreUnknown=true) public record StatusResponse(String status,List<Submission> result,String comment){} @JsonIgnoreProperties(ignoreUnknown=true) public record Submission(String verdict,Long contestId,Problem problem){} @JsonIgnoreProperties(ignoreUnknown=true) public record Problem(String index){} }
